def slug(text):
    text = text.lower()
    result = ''
    i = 0
    while i < len(text):
        if text[i].isalnum():
            result += text[i]
            i += 1
        else:
            # Replace run of non-alphanumeric with a single hyphen
            while i < len(text) and not text[i].isalnum():
                i += 1
            result += '-'
    # Strip edge hyphens
    result = result.strip('-')
    return result

